import { useLingui } from '@lingui/react/macro'
import { useLocalSearchParams, useRouter } from 'expo-router'
import licenses from '@/settings/licenses.json'
import { Group, type GroupRow, List, Paragraph } from '@/ui/primitives'
import { Screen } from '@/ui/screen'

type License = (typeof licenses)[number]

/** A package's version and licence, such as `19.3.0 · MIT`. */
function summary(license: License) {
  return [license.version, license.license].filter(Boolean).join(' · ')
}

/**
 * The open-source packages and native libraries Scale is built on, generated by
 * `scripts/generate-licenses.ts`; each opens its licence text.
 */
export function LicensesScreen() {
  const { t } = useLingui()
  const router = useRouter()

  const rows: GroupRow[] = licenses.map((license) => ({
    key: license.name,
    label: license.name,
    value: summary(license),
    drillIn: true,
    onPress: () => router.push({ pathname: '/licenses/[name]', params: { name: license.name } }),
  }))

  return (
    <Screen
      title={t({
        message: 'Licenses',
        comment: 'Title of the screen listing the open-source software the app uses',
      })}
      appBar='large'
      navigation='back'
    >
      <List grouped>
        <Group rows={rows} />
      </List>
    </Screen>
  )
}

/** One package's licence text, a paragraph to each lazy row. */
export function LicenseScreen() {
  const { t } = useLingui()
  const { name } = useLocalSearchParams<{ name: string }>()
  const license = licenses.find((entry) => entry.name === name)
  const kind = license?.license

  const text =
    license?.text ??
    (kind
      ? t({
          message: `Released under the ${kind} license. The package includes no license text.`,
          comment: 'Shown for a package without a license file; the license is a name like MIT',
        })
      : '')

  const heading = license ? summary(license) : ''

  return (
    <Screen title={name ?? ''} appBar='large' navigation='back'>
      <List bottomPadding={32}>
        {heading ? <Paragraph key='heading'>{heading}</Paragraph> : null}
        {text
          ? text
              .split('\n\n')
              .map((paragraph, index) => <Paragraph key={index}>{paragraph}</Paragraph>)
          : null}
      </List>
    </Screen>
  )
}
